package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import com.ruoyi.common.core.constant.SecurityConstants;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;

/** A TK owns immutable source-specific return plans. Only warehouse facts can restore stock. */
@Service public class RefundGoodsService {
    @Resource RefundService refunds;
    @Resource RefundReturnClient returns;
    @Resource RefundSharedScope sharedScope;
    @Resource OrderWarehouseClient inventory;
    @Resource OrderCatalog catalog;
    private OrderRepository r(){return refunds.repository;}
    private Map<String,Object> plan(String c,long refund,long id,boolean lock){List<Map<String,Object>> found=r().db().query("SELECT * FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND id=?"+(lock?" FOR UPDATE":""),ROW,c,refund,id);require(found.size()==1,"退回安排不存在或不属于本退款单");return found.get(0);}
    private Map<String,Object> editable(String c,long id,Map<String,Object> input){Map<String,Object> b=refunds.business(c,id,true),p=refunds.platform(c,number(b,"platform_refund_id"),true);require(number(b,"control_version")==number(input,"control_version"),"退款单已变化，请刷新");require("APPROVED".equals(text(b,"review_state"))&&number(b,"approved_version")==number(p,"version")&&"VALID".equals(text(p,"source_state")),"请先审核当前可信的平台退款版本");require(!"CLOSED".equals(text(p,"platform_status"))||"SUCCESS".equals(text(b,"funds_state")),"平台申请已关闭，请先截停并核对货物，再确认关闭后的货物处置");require(!"DONE".equals(text(b,"goods_state")),"货物已结案，请核对原处理记录");return b;}
    public Map<String,Object> report(String c,long id){Map<String,Object> b=refunds.business(c,id,false);List<Map<String,Object>> plans=r().db().query("SELECT * FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? ORDER BY id LIMIT 100",ROW,c,id);for(Map<String,Object> p:plans){p.remove("lease_token");p.remove("parcel_lease_token");p.remove("request_json");p.put("actual",p.get("result_json")==null?null:obj(p.get("result_json")));p.remove("result_json");}return m("plans",plans,"bundle_returns",RefundBundleReturns.report(r(),c,id),"goods_state",b.get("goods_state"));}
    public Map<String,Object> options(String c,long id){refunds.business(c,id,false);List<Map<String,Object>> stores=new ArrayList<>();for(Map<String,Object> w:catalog.warehouses(c))stores.add(m("code",w.get("wms_simulation_code"),"name",w.get("wms_simulation_name")));return m("warehouses",stores);}
    private Map<String,Object> source(String c,Map<String,Object> b,long line,boolean lock){List<Map<String,Object>> found=r().db().query("SELECT l.*,s.shipment_sn,s.stock_reference,s.order_id,s.owner_code original_owner,ol.stock_reference line_reference FROM oms_order_shipment_line l JOIN oms_order_shipment s ON s.company_code=l.company_code AND s.id=l.shipment_id JOIN oms_order_line ol ON ol.company_code=l.company_code AND ol.id=l.order_line_id WHERE l.company_code=? AND s.order_id=? AND ol.platform_oid=? AND l.id=?"+(lock?" FOR UPDATE":""),ROW,c,b.get("order_id"),b.get("platform_oid"),line);require(found.size()==1&&number(found.get(0),"shipped_quantity")>0,"请选择本子单实际发出的商品明细");return found.get(0);}
    private long capacity(String c,Map<String,Object> s,long excluded,long refund){r().db().query("SELECT id FROM oms_order_line WHERE company_code=? AND id=? FOR UPDATE",ROW,c,s.get("order_line_id"));return Math.max(0,number(s,"shipped_quantity")-ReturnSourceClaims.refundUsed(r(),c,number(s,"id"),excluded,refund)-ReturnSourceClaims.exchangeUsed(r(),c,number(s,"id")));}
    void verifyParcelScope(String c,Map<String,Object> b,Map<String,Object> p){Map<String,Object> s=source(c,b,number(p,"shipment_line_id"),true);require(number(p,"waived_quantity")==0&&number(p,"quantity")<=capacity(c,s,number(p,"id"),number(b,"id")),"原发货来源额度已变化或已不再追回，不能补充关联");}
    public Map<String,Object> create(String c,long id,Map<String,Object> input,String actor){
        Map<String,Object> hint=refunds.business(c,id,false),s=source(c,hint,number(input,"shipment_line_id"),false);String reference=text(s,"stock_reference");if(reference.isEmpty())reference=text(s,"line_reference");if(reference.isEmpty())reference=text(hint,"platform_tid");
        Map<String,Object> basis=data(inventory.returnBasis(c,m("allocation_ids",Collections.singletonList(s.get("allocation_id")),"channel_id",hint.get("channel_id"),"platform_tid",reference,"platform_oid",hint.get("platform_oid"),"sku_sn",s.get("sku_sn")),SecurityConstants.INNER));basis.put("owner_code",s.get("original_owner"));basis.put("original_shipment_sn",s.get("shipment_sn"));basis.put("source_shipment_line_id",s.get("id"));
        long plan=refunds.tx().execute(tx->{Map<String,Object> b=editable(c,id,input);require(Arrays.asList("INTERCEPT","REFUSAL","RETURN").contains(text(b,"goods_action")),"当前方案无需建立退回安排");require(Boolean.TRUE.equals(input.get("confirmed")),"请明确确认本次实际退回范围");String key=required(input,"request_key",64),store=required(input,"store_code",64),address=required(input,"return_address",500),contact=required(input,"return_contact",200),reason=required(input,"reason",500),evidence=required(input,"evidence",1000);require(key.matches("[A-Za-z0-9_-]{8,64}"),"请求标识无效");long qty=number(input,"quantity");RefundBundleReturns.guardSource(r(),c,id,number(s,"id"),qty,store,address,contact);require(qty>0&&qty<=100000000,"请填写明确的退回数量");require(number(basis,"quantity")>=qty,"库存原出库台账数量不足，请先核对原发货来源，不会扩大退回数量");
            List<Map<String,Object>> old=r().db().query("SELECT * FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND (request_key=? OR shipment_line_id=?) FOR UPDATE",ROW,c,id,key,s.get("id"));if(!old.isEmpty()){Map<String,Object> p=old.get(0);require(old.size()==1&&number(p,"shipment_line_id")==number(s,"id")&&qty==number(p,"quantity")&&store.equals(text(p,"store_code"))&&address.equals(text(p,"return_address"))&&contact.equals(text(p,"return_contact")),"已有来源安排，请在原退回单截单或重新安排，不能覆盖重建");return number(p,"id");}
            require(catalog.warehouses(c).stream().anyMatch(w->store.equals(text(w,"wms_simulation_code"))),"退回仓不属于当前公司");Map<String,Object> actualSource=source(c,b,number(s,"id"),true);require(qty<=capacity(c,actualSource,0,id),"原发货数量已被退款或换货退回占用，请核对实际来源额度");
            Map<String,Object> command=m("refund_id",id,"refund_sn",b.get("refund_sn"),"order_sn",b.get("order_sn"),"platform_tid",b.get("platform_tid"),"store_code",store,"goods_name",s.get("goods_name"),"sku_sn",s.get("sku_sn"),"quantity",qty,"return_basis",basis,"return_address",address,"return_contact",contact,"sender",Collections.emptyMap());
            long p=r().insert("INSERT INTO oms_refund_return_plan(company_code,refund_id,shipment_line_id,shipment_id,shipment_sn,sku_sn,quantity,store_code,return_address,return_contact,package_ids,return_mode,request_key,reason,evidence,actor,request_json,return_waybill) VALUES (?,?,?,?,?,?,?,?,?,?,'[]',?,?,?,?,?,?,?)",c,id,s.get("id"),s.get("shipment_id"),s.get("shipment_sn"),s.get("sku_sn"),qty,store,address,contact,b.get("goods_action"),key,reason,evidence,actor,encode(command),text(input,"return_waybill"));touch(c,id,"WAIT_RETURN","创建退回安排 #"+p+"："+qty+" 件；依据："+reason+"；凭证："+evidence,actor);return p;});return m("id",plan);
    }
    private String operationLabel(String action){return text(m("dispatch","下发仓库","query","查询仓库原单","retry","重试下发","posting","核对原实收记账","cancel","退回截单","rearrange","重新安排剩余退回","review","人工核对"),action);}
    private void touch(String c,long id,String goods,String message,String actor){r().db().update("UPDATE oms_refund SET goods_state=?,state=IF(review_state='APPROVED','PROCESSING',state),control_version=control_version+1 WHERE company_code=? AND id=?",goods,c,id);refunds.event(c,id,"GOODS",message,actor);}
    public Map<String,Object> action(String c,long id,long planId,long document,String action,Map<String,Object> input,String actor){require(Arrays.asList("dispatch","query","retry","posting","cancel","rearrange","review","waive","logistics","stop").contains(action),"退回操作无效");String lease=token();
        refunds.tx().execute(tx->{Map<String,Object> b=Arrays.asList("query","posting","review","cancel","stop").contains(action)?refunds.business(c,id,true):editable(c,id,input);Map<String,Object> p=plan(c,id,planId,true);require(number(input,"plan_version")==number(p,"control_version"),"退回安排已变化，请刷新");require(r().db().update("UPDATE oms_refund_return_plan SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,c,planId)==1,"退回安排正在处理，请稍后核对");
            if(Arrays.asList("dispatch","retry","rearrange").contains(action)){require(!"NEED_CHECK".equals(text(p,"parcel_state"))&&!Arrays.asList("WAIT_BUYER","WAREHOUSE_CHECK").contains(text(p,"parcel_resolution")),"合包归属尚未核对，请先处理合包问题，不能直接下发或重建退回单");}if(Arrays.asList("dispatch","retry","rearrange").contains(action))require(!Arrays.asList("CLOSED","RELEASED").contains(text(p,"state")),"退回安排已经结束");
            if("review".equals(action)&&"ACCEPT".equals(text(input,"decision"))){Map<String,Object> s=source(c,b,number(p,"shipment_line_id"),true);require(number(p,"quantity")<=capacity(c,s,planId,id)&&number(p,"waived_quantity")==0&&!"DONE".equals(text(b,"goods_state")),"原来源额度已被占用或已差异结案，不能直接接收迟到回传");}return null;});
        try{Map<String,Object> p=plan(c,id,planId,false);Map<String,Object> command=obj(p.get("request_json"));Map<String,Object> actual=p.get("result_json")==null?null:obj(p.get("result_json"));if(actual==null&&"LINKED".equals(text(p,"parcel_state"))&&!"dispatch".equals(action)){for(Map<String,Object> parcel:data(returns.parcels(c,id,SecurityConstants.INNER)))if(parcel.get("warehouse_document")!=null){actual=data(returns.detail(c,planId,SecurityConstants.INNER));save(c,id,planId,actual);break;}}Map<String,Object> body=new LinkedHashMap<>(input);body.put("actor",actor);
            if("logistics".equals(action)){String state=required(input,"transport_state",24),waybill=required(input,"return_waybill",128),evidence=required(input,"evidence",1000);require(Arrays.asList("WAITING","IN_TRANSIT","REFUSED","INTERCEPTED","DELIVERED").contains(state),"退回物流状态无效");r().db().update("UPDATE oms_refund_return_plan SET transport_state=?,return_waybill=?,transport_evidence=?,control_version=control_version+1 WHERE company_code=? AND id=?",state,waybill,evidence,c,planId);refunds.event(c,id,"RETURN_LOGISTICS","退回物流："+state+"；运单："+waybill+"；凭证："+evidence+"；不代表仓库实收，不改变库存",actor);}
            else if("stop".equals(action)){
                require(Boolean.TRUE.equals(input.get("confirmed")),"请确认截停本退回计划的全部未完成安排");String why=required(input,"reason",500),evidence=required(input,"evidence",1000);
                if(actual==null){if("LINKED".equals(text(p,"parcel_state")))data(returns.detachParcel(c,id,planId,SecurityConstants.INNER));r().db().update("UPDATE oms_refund_return_plan SET state='STOPPED',control_version=control_version+1 WHERE company_code=? AND id=?",c,planId);}
                else{
                    actual=data(returns.detail(c,planId,SecurityConstants.INNER));save(c,id,planId,actual);
                    for(Map<String,Object> d:new ArrayList<>(listDocuments(actual))){
                        if("CONFIRMED".equals(text(d,"cancel_state"))||"COMPLETED".equals(text(d,"receipt_state")))continue;
                        Map<String,Object> stop=m("mode","WITHDRAW","reason",why,"evidence",evidence,"actor",actor,"document_version",d.get("control_version"));
                        actual=data(returns.document(c,planId,number(d,"id"),"cancel",stop,SecurityConstants.INNER));save(c,id,planId,actual);
                    }
                }
                refunds.event(c,id,"RETURN_STOP","退回计划 #"+planId+" 已逐单申请截停全部未完成安排；以各单仓库确认结果为准，不撤销已入账，不自动处理待核对回传；依据："+why+"；凭证："+evidence,actor);
            }
            else if("waive".equals(action)){if(actual!=null){actual=data(returns.detail(c,planId,SecurityConstants.INNER));save(c,id,planId,actual);p=plan(c,id,planId,false);}require(actual==null||closed(actual),"请先截停全部退回安排并处理实收与待核对回传");String why=required(input,"reason",500),evidence=required(input,"evidence",1000);long remaining=number(p,"quantity")-number(p,"accepted_quantity");require(Boolean.TRUE.equals(input.get("confirmed"))&&remaining>0&&number(input,"quantity")==remaining,"请明确确认终止追回的剩余数量");r().db().update("UPDATE oms_refund_return_plan SET waived_quantity=?,state='CLOSED',parcel_issue=NULL,parcel_state='CLOSED',parcel_error='',parcel_resolution='NOT_RETRIEVED',reason=?,evidence=?,actor=?,control_version=control_version+1 WHERE company_code=? AND id=? AND lease_token=?",remaining,why,evidence,actor,c,planId,lease);refunds.event(c,id,"GOODS_WAIVE","退回安排 #"+planId+" 终止追回 "+remaining+" 件，不增加库存；依据："+why+"；凭证："+evidence,actor);}
            else if(actual==null&&"cancel".equals(action)){required(input,"reason",500);if("LINKED".equals(text(p,"parcel_state")))data(returns.detachParcel(c,id,planId,SecurityConstants.INNER));r().db().update("UPDATE oms_refund_return_plan SET state='STOPPED',control_version=control_version+1 WHERE company_code=? AND id=?",c,planId);refunds.event(c,id,"RETURN_CANCEL","尚未下发的退回安排已本地停止；"+text(input,"reason"),actor);}
            else if(actual==null&&"rearrange".equals(action)){require("STOPPED".equals(text(p,"state")),"请先停止原安排");required(input,"reason",500);for(String key:Arrays.asList("store_code","return_address","return_contact"))command.put(key,required(input,key,key.equals("return_address")?500:200));r().db().update("UPDATE oms_refund_return_plan SET request_json=?,store_code=?,return_address=?,return_contact=?,state='PLANNED',control_version=control_version+1 WHERE company_code=? AND id=?",encode(command),command.get("store_code"),command.get("return_address"),command.get("return_contact"),c,planId);refunds.event(c,id,"RETURN_REARRANGE","未下发安排已更新；"+text(input,"reason"),actor);}
            else{if("dispatch".equals(action)&&document==0){require("PLANNED".equals(text(p,"state")),"原安排已提交，请核对原仓库结果");if(sharedScope!=null){Map<String,Object> scope=sharedScope.validate(c,id,planId);if(scope!=null)command.put("parcel_version",scope.get("control_version"));}actual=data(returns.prepare(c,planId,command,SecurityConstants.INNER));save(c,id,planId,actual);actual=data(returns.detail(c,planId,SecurityConstants.INNER));}else{require(actual!=null,"尚未下发，无仓库任务可查询");actual=data(returns.document(c,planId,document,action,body,SecurityConstants.INNER));}save(c,id,planId,actual);refunds.event(c,id,"RETURN_DOCUMENT","退回安排 #"+planId+" 操作："+operationLabel(action)+"；原单与实收入账保留；"+text(input,"reason"),actor);}
            recompute(c,id);return report(c,id);
        }finally{r().db().update("UPDATE oms_refund_return_plan SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",c,planId,lease);}
    }
    private boolean closed(Map<String,Object> a){if(number(a,"pending_review_count")>0||number(a,"accepted_quantity")!=number(a,"posted_quantity"))return false;if(listDocuments(a).isEmpty())return false;for(Map<String,Object> d:listDocuments(a))if(!"CONFIRMED".equals(text(d,"cancel_state"))&&!"COMPLETED".equals(text(d,"receipt_state")))return false;return true;}
    @SuppressWarnings("unchecked") private List<Map<String,Object>> listDocuments(Map<String,Object> a){return a.get("documents") instanceof List?(List<Map<String,Object>>)a.get("documents"):a.containsKey("id")?Collections.singletonList(a):Collections.emptyList();}
    private void save(String c,long id,long plan,Map<String,Object> a){String state=number(a,"pending_review_count")>0?"WAIT_REVIEW":closed(a)?"STOPPED":number(a,"accepted_quantity")>0?"PARTIAL":"ACTIVE";r().db().update("UPDATE oms_refund_return_plan SET accepted_quantity=?,posted_quantity=?,result_json=?,state=IF(state='CLOSED',state,?),last_error='',control_version=control_version+1,next_check=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND refund_id=? AND id=?",a.get("accepted_quantity"),a.get("posted_quantity"),encode(a),state,c,id,plan);}
    void recompute(String c,long id){refunds.tx().execute(tx->{Map<String,Object> b=refunds.business(c,id,true);List<Map<String,Object>> plans=r().db().query("SELECT * FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? ORDER BY id FOR UPDATE",ROW,c,id);if(plans.isEmpty())return null;String state="WAIT_RETURN";boolean all=true;for(Map<String,Object> p:plans){if(number(p,"accepted_quantity")!=number(p,"posted_quantity")||number(p,"posted_quantity")+number(p,"waived_quantity")!=number(p,"quantity"))all=false;if("WAIT_REVIEW".equals(text(p,"state"))||(p.get("result_json")!=null&&number(obj(p.get("result_json")),"pending_review_count")>0)){state="WAIT_CHECK";break;}if(number(p,"accepted_quantity")>0)state="PART_RETURNED";}if(all&&!"WAIT_CHECK".equals(state))state="WAIT_QC";if("WAIT_CHECK".equals(state)&&"DONE".equals(text(b,"goods_state")))r().db().update("UPDATE oms_refund SET state='BLOCKED',goods_state='WAIT_CHECK',problem_code='RETURN_REVIEW',problem_message='结案后仍收到待核对回传，请核对原退回单',control_version=control_version+1 WHERE company_code=? AND id=?",c,id);if(!"DONE".equals(text(b,"goods_state")))r().db().update("UPDATE oms_refund SET control_version=IF(goods_state<>?,control_version+1,control_version),goods_state=? WHERE company_code=? AND id=?",state,state,c,id);RefundGuard.refresh(r(),c,number(b,"channel_id"),text(b,"platform_tid"));return null;});}
    public Map<String,Object> finish(String c,long id,Map<String,Object> input,String actor){RefundBundleReturns.guardComplete(r(),c,id);refresh(c,id);refunds.tx().execute(tx->{Map<String,Object> b=editable(c,id,input);require(Boolean.TRUE.equals(input.get("confirmed")),"请确认本次退回范围及全部差异已核对");String why=required(input,"reason",500),evidence=required(input,"evidence",1000);List<Map<String,Object>> plans=r().db().query("SELECT * FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? ORDER BY id FOR UPDATE",ROW,c,id);require(!plans.isEmpty(),"请先明确退回安排；无需追回请使用独立差异结案");for(Map<String,Object> p:plans){require(p.get("lease_until")==null||!time(text(p,"lease_until")).isAfter(java.time.LocalDateTime.now()),"退回安排正在处理");Map<String,Object> a=p.get("result_json")==null?null:obj(p.get("result_json"));require(number(p,"accepted_quantity")==number(p,"posted_quantity")&&number(p,"posted_quantity")+number(p,"waived_quantity")==number(p,"quantity")&&(a==null||closed(a)),"存在待收、待记账、未截停安排或待人工核对回传");r().db().update("UPDATE oms_refund_return_plan SET qc_state='PASSED',qc_reason=?,state='CLOSED' WHERE company_code=? AND id=?",why,c,p.get("id"));}complete(c,id,why,evidence,actor);return null;});return report(c,id);}
    public Map<String,Object> closeWithdrawn(String c,long id,Map<String,Object> input,String actor){
        refresh(c,id);refunds.tx().execute(tx->{Map<String,Object> b=refunds.business(c,id,true),p=refunds.platform(c,number(b,"platform_refund_id"),true);require("VALID".equals(text(p,"source_state"))&&"CLOSED".equals(text(p,"platform_status"))&&!"SUCCESS".equals(text(b,"funds_state")),"仅平台申请已关闭且无退款成功事实时可结束关闭后的货物事项");require(number(input,"control_version")==number(b,"control_version")&&Boolean.TRUE.equals(input.get("confirmed")),"退款信息已变化或尚未确认，请刷新核对");String why=required(input,"reason",500),evidence=required(input,"evidence",1000);
            for(Map<String,Object> plan:r().db().query("SELECT * FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? ORDER BY id FOR UPDATE",ROW,c,id)){require(plan.get("lease_until")==null||!time(text(plan,"lease_until")).isAfter(java.time.LocalDateTime.now()),"退回计划仍在处理，请稍后核对");require(number(plan,"accepted_quantity")==number(plan,"posted_quantity")&&(plan.get("result_json")==null?"STOPPED".equals(text(plan,"state")):closed(obj(plan.get("result_json")))),"仍有仓库安排、未入账实收或待核对回传，请先逐单处理；不能直接关闭");r().db().update("UPDATE oms_refund_return_plan SET waived_quantity=quantity-accepted_quantity,state='CLOSED',qc_reason=? WHERE company_code=? AND id=?",why,c,plan.get("id"));}
            r().db().update("UPDATE oms_refund SET state='CLOSED',goods_state='DONE',review_state='CLOSED',approved_version=?,problem_code='',problem_message='',control_version=control_version+1 WHERE company_code=? AND id=?",p.get("version"),c,id);refunds.event(c,id,"CLOSED_GOODS","平台申请关闭后货物处置已确认；已入账保留，未退回范围终止，不伪造平台退款；依据："+why+"；凭证："+evidence,actor);RefundGuard.refresh(r(),c,number(b,"channel_id"),text(b,"platform_tid"));return null;});return report(c,id);
    }
    public Map<String,Object> waiveAll(String c,long id,Map<String,Object> input,String actor){refunds.tx().execute(tx->{Map<String,Object> b=editable(c,id,input);require(Arrays.asList("REFUSAL","INTERCEPT","RETURN").contains(text(b,"goods_action")),"当前货物方案不支持无需追回");require(Boolean.TRUE.equals(input.get("confirmed")),"请确认无需追回不代表收货，不增加库存");require(r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND refund_id=?",Long.class,c,id)==0&&r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_bundle_return WHERE company_code=? AND refund_id=?",Long.class,c,id)==0,"已有退回范围，请继续建立组件安排后逐项截停、差异处理并结案");long unshipped=r().db().queryForObject("SELECT COALESCE(SUM(GREATEST(l.quantity-l.cancelled_quantity-(SELECT COALESCE(SUM(s.shipped_quantity),0) FROM oms_order_shipment_line s WHERE s.company_code=l.company_code AND s.order_line_id=l.id),0)),0) FROM oms_order_line l WHERE l.company_code=? AND l.order_id=? AND l.platform_oid=?",Long.class,c,b.get("order_id"),b.get("platform_oid"));require(unshipped==0,"仍有未发商品，请先明确未发部分的取消或继续履约方案");complete(c,id,"无需追回："+required(input,"reason",500),required(input,"evidence",1000),actor);return null;});return report(c,id);}
    public Map<String,Object> cancelUnshipped(String c,long id,Map<String,Object> input,String actor){
        Map<String,Object> command=refunds.tx().execute(tx->{Map<String,Object> b=editable(c,id,input);require("CANCEL".equals(text(b,"goods_action"))&&number(b,"cancel_quantity")>0,"请先审核明确的取消商品与数量");if(b.get("cancel_command")!=null)return obj(b.get("cancel_command"));
            List<Map<String,Object>> rows=r().db().query("SELECT * FROM oms_order_line WHERE company_code=? AND order_id=? AND id=? AND platform_oid=? FOR UPDATE",ROW,c,b.get("order_id"),b.get("cancel_line_id"),b.get("platform_oid"));require(rows.size()==1,"取消商品来源已变化");Map<String,Object> l=rows.get(0);long shipped=r().db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND order_line_id=?",Long.class,c,l.get("id"));require(number(b,"cancel_quantity")<=number(l,"quantity")-number(l,"cancelled_quantity")-shipped,"未发数量已变化，请核对出库结果");require(r().db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_line sl JOIN oms_order_shipment sh ON sh.company_code=sl.company_code AND sh.id=sl.shipment_id WHERE sl.company_code=? AND sl.order_line_id=? AND sh.status NOT IN ('VOIDED','CLOSED') AND sl.quantity>sl.shipped_quantity+sl.cancelled_quantity",Long.class,c,l.get("id"))==0,"仍有发货安排，请先到原订单撤回并确认仓库截停，再执行取消；不会自动取消其他商品");
            String reference=text(l,"stock_reference").isEmpty()?text(b,"platform_tid"):text(l,"stock_reference");require(r().db().queryForObject("SELECT COUNT(*) FROM oms_order_line WHERE company_code=? AND order_id=? AND platform_oid=? AND sku_sn=? AND COALESCE(NULLIF(stock_reference,''),?)=?",Long.class,c,b.get("order_id"),b.get("platform_oid"),l.get("sku_sn"),b.get("platform_tid"),reference)==1,"库存来源不唯一，请人工核对");
            Map<String,Object> request=m("request_id","CFTK"+id,"mode","REDUCE","channel_id",b.get("channel_id"),"platform_tid",reference,"allocations",Collections.emptyList(),"demands",Collections.singletonList(m("platform_oid",b.get("platform_oid"),"sku_sn",l.get("sku_sn"),"quantity",b.get("cancel_quantity"))));r().db().update("UPDATE oms_refund SET cancel_command=?,control_version=control_version+1 WHERE company_code=? AND id=?",encode(request),c,id);refunds.event(c,id,"CANCEL_REQUEST","已固定未发取消请求；库存结果不明时沿用原请求核对，不重复创建",actor);return request;});
        Map<String,Object> receipt=data(inventory.adjust(c,command,SecurityConstants.INNER));refunds.tx().execute(tx->{Map<String,Object> b=refunds.business(c,id,true);String cancelledSku=r().db().queryForObject("SELECT sku_sn FROM oms_order_line WHERE company_code=? AND order_id=? AND id=?",String.class,c,b.get("order_id"),b.get("cancel_line_id"));Map<String,Object> selected=null;for(Map<String,Object> row:list(receipt.get("lines")))if(text(b,"platform_oid").equals(text(row,"platform_oid"))&&cancelledSku.equals(text(row,"sku_sn"))){require(selected==null,"取消回执来源不唯一");selected=row;}require(selected!=null&&"COMPLETED".equals(text(receipt,"state")),"取消回执尚未完成，请核对原请求");r().db().update("UPDATE oms_order_line SET cancelled_quantity=?,reserved_quantity=?,inventory_reason='退款终止指定未发需求' WHERE company_code=? AND order_id=? AND id=?",selected.get("cancelled_quantity"),selected.get("reserved_quantity"),c,b.get("order_id"),b.get("cancel_line_id"));r().db().update("UPDATE oms_refund SET cancelled_quantity=cancel_quantity WHERE company_code=? AND id=?",c,id);r().db().update("UPDATE oms_order SET review_status='PENDING',review_decision='MANUAL_REQUIRED',review_reason='退款取消后剩余需求待核对',review_by='',review_at=NULL,review_snapshot=NULL,control_version=control_version+1 WHERE company_code=? AND id=?",c,b.get("order_id"));complete(c,id,"已按原库存请求取消指定未发商品 "+number(b,"cancel_quantity")+" 件","库存回执 "+text(command,"request_id"),actor);return null;});return report(c,id);
    }
    private void complete(String c,long id,String why,String evidence,String actor){r().db().update("UPDATE oms_refund SET goods_state='DONE',state=IF(funds_state='SUCCESS','COMPLETED','PROCESSING'),control_version=control_version+1 WHERE company_code=? AND id=?",c,id);refunds.event(c,id,"GOODS_COMPLETE",why+"；凭证："+evidence+"；未凭结案操作调整库存",actor);Map<String,Object> b=refunds.business(c,id,false);RefundGuard.refresh(r(),c,number(b,"channel_id"),text(b,"platform_tid"));}
    public void refresh(String c,long id){refunds.business(c,id,false);for(Map<String,Object> p:r().db().query("SELECT * FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND (result_json IS NOT NULL OR parcel_state='LINKED') ORDER BY id LIMIT 100",ROW,c,id)){String lease=token();if(r().db().update("UPDATE oms_refund_return_plan SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,c,p.get("id"))!=1)throw new IllegalArgumentException("退回安排正在处理，请稍后刷新");try{if(p.get("result_json")==null){boolean dispatched=false;for(Map<String,Object> box:data(returns.parcels(c,id,SecurityConstants.INNER)))if(box.get("warehouse_document")!=null)dispatched=true;if(!dispatched)continue;}Map<String,Object> a=data(returns.detail(c,number(p,"id"),SecurityConstants.INNER));if(number(a,"accepted_quantity")>number(a,"posted_quantity")){long document=number(a,"id");a=data(returns.document(c,number(p,"id"),document,"posting",Collections.emptyMap(),SecurityConstants.INNER));}save(c,id,number(p,"id"),a);}finally{r().db().update("UPDATE oms_refund_return_plan SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",c,p.get("id"),lease);}}recompute(c,id);}
    public void scan(String c){try{returns.reconcileAutomatic(c,SecurityConstants.INNER);}catch(RuntimeException pending){}try{for(Map<String,Object> dirty:data(returns.pending(c,SecurityConstants.INNER))){long plan=number(dirty,"plan_id");List<Long> ids=r().db().queryForList("SELECT refund_id FROM oms_refund_return_plan WHERE company_code=? AND id=?",Long.class,c,plan);if(ids.isEmpty())continue;try{refresh(c,ids.get(0));Map<String,Object> p=plan(c,ids.get(0),plan,false);if(number(p,"accepted_quantity")==number(p,"posted_quantity"))data(returns.acknowledge(c,plan,dirty,SecurityConstants.INNER));}catch(RuntimeException ignored){}}}catch(RuntimeException unavailable){}for(Long id:r().db().queryForList("SELECT DISTINCT refund_id FROM oms_refund_return_plan WHERE company_code=? AND (result_json IS NOT NULL OR parcel_state='LINKED') AND state<>'CLOSED' AND next_check<=NOW() ORDER BY refund_id LIMIT 20",Long.class,c))try{refresh(c,id);}catch(RuntimeException failure){r().db().update("UPDATE oms_refund_return_plan SET last_error='仓库进度核对失败，请刷新原退回单',next_check=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND refund_id=?",c,id);}}
}
